using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class DenseImpactCheck{
 public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");if(!g.TryStartRun(42))throw new Exception("Start failed");g.SetPaused(true);var f=BindingFlags.Instance|BindingFlags.NonPublic;var list=(IList)typeof(RunSimulator).GetField("enemies",f).GetValue(g.Run);list.Clear();for(int i=0;i<80;i++){var e=new EnemyState();Set(e,"Id",10000+i);Set(e,"Kind",(EnemyKind)(i%7));Set(e,"X",(double)(-320+(i%10)*70));Set(e,"Y",(double)(-240+(i/10)*76));Set(e,"Hp",10d);Set(e,"MaxHp",10d);list.Add(e);}var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",f).GetValue(g);w.Reset(g.Run);g.PresentBattle();if(w.ActiveEnemies!=80)throw new Exception("Missing enemies");var root=(GameObject)typeof(InkBattleWorld).GetField("root",f).GetValue(w);int initial=root.GetComponentsInChildren<SpriteRenderer>(true).Length;for(int n=0;n<20;n++)g.PresentBattle();int after=root.GetComponentsInChildren<SpriteRenderer>(true).Length;if(after!=initial)throw new Exception("Renderer growth without ticks");var attack=typeof(InkBattleWorld).GetMethod("Attack",f);var fx=(IList)typeof(InkBattleWorld).GetField("effects",f).GetValue(w);
string snapshot=JsonUtility.ToJson(g.Run.CaptureState());
for(int k=0;k<8;k++){var hit=new AttackEvent();typeof(AttackEvent).GetProperty("Weapon").SetValue(hit,WeaponKind.Point);typeof(AttackEvent).GetProperty("TargetX").SetValue(hit,(double)(-280+k*80));typeof(AttackEvent).GetProperty("TargetY").SetValue(hit,(double)(80+(k%3)*85));attack.Invoke(w,new object[]{hit,g.Run,false});}
foreach(var effect in fx)effect.GetType().GetField("age").SetValue(effect,.08f);
g.SetReducedMotion(false);g.PresentBattle();int effects=fx.Count;if(effects>128||effects<40)throw new Exception("Unexpected dense effects");
if(snapshot!=JsonUtility.ToJson(g.Run.CaptureState()))throw new Exception("Presentation changed fixture");if(after!=initial)throw new Exception("Renderer growth without ticks");var mask=(Texture2D)typeof(BokumyakuGame).GetField("burstInk",f).GetValue(g);var pixels=mask.GetPixels32();int opaque=0;foreach(var pixel in pixels)if(pixel.a>=200)opaque++;File.WriteAllBytes("../docs/evidence/impact-mask.png",mask.EncodeToPNG());var result=new{passed=true,opaqueMaskPixels=opaque,enemies=w.ActiveEnemies,rendererBefore=initial,rendererAfter=after,renderCalls=20,effects,snapshotUnchanged=true,scope="Artificial 80-enemy seven-kind static fixture with injected Point impacts; not balance, performance or natural wave evidence"};File.WriteAllText(Path.GetFullPath("../docs/evidence/dense-impact-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/dense-impact-check.png"));return result;}
 static void Set(EnemyState e,string name,object value){typeof(EnemyState).GetProperty(name).SetValue(e,value);}
}




